// UpdateStoreProfile edits the seller's own listing details.
func (r *mutationResolver) UpdateStoreProfile(ctx context.Context, input model.StoreProfileInput) (*model.Store, error) {
	tenantID, err := requireTenant(ctx)
	if err != nil {
		return nil, err
	}

	// Three-way per field: NULL (omitted) leaves it untouched, an empty
	// string clears it, anything else sets it. A plain COALESCE would give
	// only the first two-thirds — a seller could never remove a tagline or
	// swap out a logo once one had been set.
	//
	// The name is the exception: a stall must always have one, so an empty
	// name is treated as "leave it alone" rather than "erase it".
	_, err = r.DB.Exec(ctx, `
        UPDATE tenants SET
            name        = COALESCE(NULLIF($2, ''), name),
            tagline     = CASE WHEN $3::text IS NULL THEN tagline     WHEN $3 = '' THEN NULL ELSE $3 END,
            description = CASE WHEN $4::text IS NULL THEN description WHEN $4 = '' THEN NULL ELSE $4 END,
            category    = CASE WHEN $5::text IS NULL THEN category    WHEN $5 = '' THEN NULL ELSE $5 END,
            location    = CASE WHEN $6::text IS NULL THEN location    WHEN $6 = '' THEN NULL ELSE $6 END,
            logo_url    = CASE WHEN $7::text IS NULL THEN logo_url    WHEN $7 = '' THEN NULL ELSE $7 END
        WHERE id = $1
    `, tenantID, derefOr(input.Name, ""), input.Tagline, input.Description,
		input.Category, input.Location, input.LogoURL)
	if err != nil {
		return nil, fmt.Errorf("failed to update stall: %w", err)
	}

	return r.fetchStore(ctx, "t.id = $1", tenantID)
}

// SubmitStoreForReview puts a pending or rejected stall into the queue.
func (r *mutationResolver) SubmitStoreForReview(ctx context.Context) (*model.Store, error) {
	tenantID, err := requireTenant(ctx)
	if err != nil {
		return nil, err
	}

	var status string
	if err := r.DB.QueryRow(ctx,
		`SELECT status FROM tenants WHERE id = $1`, tenantID,
	).Scan(&status); err != nil {
		return nil, fmt.Errorf("stall not found")
	}

	switch status {
	case "approved":
		return nil, fmt.Errorf("this stall is already approved")
	case "suspended":
		return nil, fmt.Errorf("suspended stalls cannot be resubmitted — contact support")
	}

	if _, err := r.DB.Exec(ctx, `
        UPDATE tenants
           SET status = 'pending', submitted_at = NOW(), review_note = NULL
         WHERE id = $1
    `, tenantID); err != nil {
		return nil, fmt.Errorf("failed to submit stall: %w", err)
	}

	if err := r.recordModeration(ctx, tenantID, "", "submit", nil); err != nil {
		return nil, fmt.Errorf("failed to record submission: %w", err)
	}

	return r.fetchStore(ctx, "t.id = $1", tenantID)
}

// AcceptTerms records the seller's acceptance of a specific terms version.
func (r *mutationResolver) AcceptTerms(ctx context.Context, version string) (bool, error) {
	tenantID, err := requireTenant(ctx)
	if err != nil {
		return false, err
	}

	version = strings.TrimSpace(version)
	if version == "" {
		return false, fmt.Errorf("a terms version is required")
	}

	userID := appMiddleware.GetUserID(ctx)
	var userIDArg any
	if userID != "" {
		userIDArg = userID
	}

	if _, err := r.DB.Exec(ctx, `
        INSERT INTO terms_acceptances (tenant_id, user_id, version)
        VALUES ($1, $2, $3)
    `, tenantID, userIDArg, version); err != nil {
		return false, fmt.Errorf("failed to record acceptance: %w", err)
	}

	return true, nil
}

