// SetStoreRestrictions is the lighter alternative to suspension: the stall
// stays listed but loses a specific capability.
func (r *mutationResolver) SetStoreRestrictions(ctx context.Context, tenantID uuid.UUID, canPublishProducts bool, canAcceptOrders bool, reason *string) (*model.Store, error) {
	adminID, err := requireAdmin(ctx)
	if err != nil {
		return nil, err
	}

	id := tenantID.String()

	action := "restrict"
	if canPublishProducts && canAcceptOrders {
		action = "unrestrict"
	}

	tx, err := r.DB.Begin(ctx)
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback(ctx) }()

	tag, err := tx.Exec(ctx, `
        UPDATE tenants
           SET can_publish_products = $2, can_accept_orders = $3
         WHERE id = $1
    `, id, canPublishProducts, canAcceptOrders)
	if err != nil {
		return nil, fmt.Errorf("failed to update restrictions: %w", err)
	}
	if tag.RowsAffected() == 0 {
		return nil, fmt.Errorf("stall not found")
	}

	if _, err := tx.Exec(ctx, `
        INSERT INTO tenant_moderation_events (tenant_id, admin_id, action, reason)
        VALUES ($1, $2, $3, $4)
    `, id, adminID, action, reason); err != nil {
		return nil, fmt.Errorf("failed to record moderation: %w", err)
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, err
	}

	return r.fetchStore(ctx, "t.id = $1", id)
}

